#include "stdafx.h"#include "DO.h"KDO::KDO(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Invert",  "Failsafe type",};BOOL KDO::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    CStringA s;    if( 0==m_CurParameterID )    {      if( !szText.compare("NO") )        s = "Invert = 0";      else        s = "Invert = 1";    }    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    AddParam( szLast.c_str(), szText.c_str() );    szLast.clear();    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      szLast = szText;      return TRUE;    }  }  return FALSE;}